state-free-credit.find:
if current_value != new_value and original_value == new_value:
    if original_value == 0:
        # Slot set then cleared: refund the state gas charge.
        credit_state_gas_refund(evm.gas_meter, StateGasCosts.STORAGE_SET)

state-free-credit.replace:
if current_value != new_value and original_value == new_value:
    if original_value == 0:
        # Slot set then cleared: refund the state gas charge.
        credit_state_gas_refund(evm.gas_meter, StateGasCosts.STORAGE_SET)
if current_value != new_value and new_value == 0 and original_value != 0:
    # MUTATION: clearing state that pre-dates the transaction earns a
    # state-gas credit, i.e. a fork that decided to PAY for freeing
    # state. Deliberately a sixteenth of a storage set (6,120) so the
    # resulting negative net stays representable in
    # `gas_used_before_refund` rather than underflowing a Uint.
    credit_state_gas_refund(
        evm.gas_meter, StateGas(StateGasCosts.STORAGE_SET // Uint(16))
    )
